INSERT INTO public.items (id, name, type, "desc") VALUES (123233, 'Pacote de dia da mentira', 200, 'Abra e consiga: Pontos de atualização do Totem*2999, Totem Pedras de runas*50. (Tem a oportunidade de ganhar um dos seguintes itens:Função Atualização Pérola Alma*50,Cascalhos*50, Pele de fera*50,Poção única Lv2*30,Figurinos ilustrados com cupons*20, Soul Crystal Box (Lg)*30,Tri Chifres de Dragão Cartões Manuais*1,Cartão Manual do Céu*1, chamar Cerberus*1,chamar Patamon*1, Carpa de lótus*1,Canhão Abóbora*1,Pérola Mágica*10,Superior Rune*1)') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, "desc" = EXCLUDED."desc";